    /// <summary>
    /// Da a un botón de categoría la apariencia de pestaña.
    /// </summary>
    private void ConfigurarCategoria(RadioButton categoria, string texto, int ancho)
    {
        categoria.Appearance = Appearance.Button;
        categoria.FlatStyle = FlatStyle.Flat;
        categoria.Font = new Font("Segoe UI", 9F, FontStyle.Bold);
        categoria.Margin = new Padding(0, 0, 8, 0);
        categoria.Size = new Size(ancho, 34);
        categoria.Text = texto;
        categoria.TextAlign = ContentAlignment.MiddleCenter;
        categoria.CheckedChanged += Categoria_CheckedChanged;
    }
